// Get the input data - fields are directly on $input.item.json
const data = $input.item.json;

// Get Product Images field
const productImages = data["Product Images"];

// Validation
if (!productImages || !Array.isArray(productImages) || productImages.length === 0) {
  throw new Error('NO product images found - add images to Products table');
}

// Extract first image
const productImageUrl = productImages[0].url;
const productFilename = productImages[0].filename;

// Return merged data
return {
  ...data,
  productImageUrl: productImageUrl,
  productFilename: productFilename
};

// Classify Ad Type - Dynamic field handling
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  // Convert any value (string, array, object) to searchable string
  const getString = (val) => {
    if (Array.isArray(val)) return val.join(' ').toLowerCase();
    if (typeof val === 'object' && val !== null) return JSON.stringify(val).toLowerCase();
    return (val || '').toLowerCase();
  };

  // Dynamically combine ALL text fields for classification
  // Excludes IDs, timestamps, URLs, and system fields
  const excludeKeys = ['id', 'adCopyRecordId', 'recordId', 'createdTime', 'url', 'n8n'];

  let combined = '';
  for (const [key, val] of Object.entries(data)) {
    if (excludeKeys.some(ex => key.toLowerCase().includes(ex))) continue;
    if (typeof val === 'string' || Array.isArray(val)) {
      combined += ' ' + getString(val);
    }
  }
  combined = combined.toLowerCase();

  // Classification rules - add new patterns here as needed
  let adType = 'Lifestyle Composite';

  const rules = [
    { type: 'Testimonial', pattern: /review|★|testimonial|ratings|quote|"i was"|"i thought"|"finally"|story|customer|said|told me/ },
    { type: 'Comparison', pattern: /\bvs\b|comparison|old way|new way|side-by-side|competitor|versus|compared to/ },
    { type: 'Before/After', pattern: /timeline|progression|before|transformation|journey|after using|results in/ },
    { type: 'Benefits Wheel', pattern: /benefit|feature|breakdown|infographic|cost|mechanism|diagram|explainer|how it works|why it works/ },
    { type: 'Product Hero', pattern: /product shot|hero|lineup|macro|packshot|unboxing|showcase|display/ }
  ];

  for (const rule of rules) {
    if (rule.pattern.test(combined)) {
      adType = rule.type;
      break;
    }
  }

  results.push({
    json: {
      ...data,
      adType: adType
    }
  });
}

return results;

const items = $input.all();

// Find S3 data (has Location field)
const s3Item = items.find(i => i.json.Location);
const s3Url = s3Item?.json?.Location || '';

// Find ad copy data (has fields object)
const adItem = items.find(i => i.json.fields);
const fields = adItem?.json?.fields || {};
const adType = adItem?.json?.adType || 'Lifestyle Composite';

const getString = (val) => {
  if (Array.isArray(val)) return val.join(', ');
  return val || '';
};

return [{
  json: {
    adType,
    headline: fields.headline || '',
    concept: fields.Concept || '',
    cta: fields.CTA || '',
    angle: fields.Angle || '',
    avatarTarget: getString(fields['Avatar Target']),
    awarenessLevel: getString(fields['Awareness Level']),
    tags: getString(fields.Tags),
    productImageUrl: s3Url,
    recordId: adItem?.json?.id || ''
  }
}];

// Parse Image Prompt Engineer output from OpenAI Chat Completions API
// and prepare the payload for ComfyUI image generation
const items = $input.all();
const results = [];

for (const item of items) {
  let text = '';

  // Primary: Standard Chat Completions response
  if (item.json?.choices?.[0]?.message?.content) {
    text = item.json.choices[0].message.content;
  }
  // Fallback: Direct text
  else if (item.json?.text) {
    text = item.json.text;
  }
  // Fallback: Responses API
  else if (item.json?.output?.[0]?.content?.[0]?.text) {
    text = item.json.output[0].content[0].text;
  }
  // Fallback: message content
  else if (item.json?.message?.content) {
    text = item.json.message.content;
  }

  // Clean markdown
  text = text.replace(/\`\`\`json\\s*/gi, '').replace(/\`\`\`\\s*/g, '').trim();

  let promptData;
  try {
    const objMatch = text.match(/\{[\s\S]*\}/);
    promptData = JSON.parse(objMatch ? objMatch[0] : text);
  } catch (e) {
    promptData = {
      prompt: text.substring(0, 500),
      negativePrompt: 'text, words, letters, logos, watermarks, blurry, low quality',
      strength: 0.55
    };
  }

  // Get upstream data preserved through the loop
  const loopItem = $('Loop Over Items3').first().json;
  const productImageUrl = loopItem?.productImageUrl || item.json?.productImageUrl || '';
  const conceptId = loopItem?.conceptId || item.json?.conceptId || 'X';
  const adCopy = loopItem?.adCopy || item.json?.adCopy || {};
  const recordId = loopItem?.recordId || item.json?.recordId || '';

  results.push({
    json: {
      prompt: promptData.prompt || '',
      negativePrompt: promptData.negativePrompt || 'text, words, letters, logos',
      strength: promptData.strength || 0.55,
      productImageUrl: productImageUrl,
      conceptId: conceptId,
      adCopy: adCopy,
      recordId: recordId
    }
  });
}

return results;

// Download product image from S3 and prepare for ComfyUI upload
// The actual upload happens in the next HTTP Request node
const productImageUrl = $json.productImageUrl || '';
const conceptId = $json.conceptId || 'X';

// Generate a unique filename for this upload
const filename = 'n8n_product_' + Date.now() + '_' + conceptId + '.jpg';

return [{
  json: {
    ...($json),
    comfyui_image_filename: filename,
    comfyui_product_url: productImageUrl
  }
}];

// Build ComfyUI API payload for Flux Dev — SCENE-ONLY generation
// Product compositing happens separately (BannerBear/Bria)
//
// Flux Dev notes:
//   CFG 1-4 works best (built-in guidance, not like SDXL)
//   Negative prompt has minimal effect — kept empty for compatibility
//   Checkpoint: flux/flux1-dev-fp8.safetensors (fp8 = 8GB VRAM friendly)

const prompt = $json.prompt || 'clean modern desk with warm morning light, minimal aesthetic';
const seed = Math.floor(Math.random() * 2147483647);
const conceptId = $json.conceptId || 'X';

// Style-specific sampler settings (from Phase 1 playbook)
const styleMap = {
  'lifestyle': { steps: 25, cfg: 3.5 },
  'product-hero': { steps: 30, cfg: 4.0 },
  'comparison': { steps: 20, cfg: 3.0 },
  'identity-mirror': { steps: 25, cfg: 3.5 },
  'emotional-story': { steps: 25, cfg: 3.5 }
};
const style = $json.style || 'lifestyle';
const s = styleMap[style] || styleMap['lifestyle'];

// ComfyUI API format
// Node IDs are arbitrary but must be consistent within the workflow
const workflowTemplate = {
  "1": {
    "class_type": "CheckpointLoaderSimple",
    "inputs": { "ckpt_name": "flux/flux1-dev-fp8.safetensors" }
  },
  "2": {
    "class_type": "CLIPTextEncode",
    "inputs": { "text": prompt, "clip": ["1", 1] }
  },
  "3": {
    "class_type": "CLIPTextEncode",
    "inputs": { "text": "", "clip": ["1", 1] }
  },
  "4": {
    "class_type": "EmptyLatentImage",
    "inputs": { "width": 1024, "height": 1280, "batch_size": 1 }
  },
  "5": {
    "class_type": "KSampler",
    "inputs": {
      "seed": seed,
      "steps": s.steps,
      "cfg": s.cfg,
      "sampler_name": "euler",
      "scheduler": "normal",
      "denoise": 1.0,
      "model": ["1", 0],
      "positive": ["2", 0],
      "negative": ["3", 0],
      "latent_image": ["4", 0]
    }
  },
  "6": {
    "class_type": "VAEDecode",
    "inputs": { "samples": ["5", 0], "vae": ["1", 2] }
  },
  "7": {
    "class_type": "SaveImage",
    "inputs": {
      "filename_prefix": "n8n_ss_" + conceptId + "_" + Date.now(),
      "images": ["6", 0]
    }
  }
};

const clientId = 'n8n-ss-' + Date.now();

return [{
  json: {
    comfyui_payload: { prompt: workflowTemplate, client_id: clientId },
    conceptId: conceptId,
    adCopy: $json.adCopy || {},
    recordId: $json.recordId || '',
    originalPrompt: prompt,
    seed: seed,
    style: style
  }
}];

// Extract generated image from ComfyUI history response
// Returns { complete: true/false } for polling loop support

const data = $json;

// Find the prompt_id in the response (it's the top-level key, a UUID)
const keys = Object.keys(data).filter(k => k.length > 20);
const promptId = keys[0] || '';

// Case 1: Not in history yet
if (!promptId || !data[promptId]) {
  return [{
    json: {
      complete: false,
      error: 'Prompt not yet in ComfyUI history'
    }
  }];
}

// Case 2: In history but not completed
const status = data[promptId].status || {};
if (!status.completed) {
  return [{
    json: {
      complete: false,
      error: 'Generation still in progress'
    }
  }];
}

// Case 3: Completed — extract image URLs
const outputs = data[promptId].outputs || {};
const images = [];
for (const nodeId in outputs) {
  if (outputs[nodeId].images) {
    for (const img of outputs[nodeId].images) {
      images.push(img);
    }
  }
}

if (images.length === 0) {
  return [{
    json: {
      complete: true,
      images: [{ url: '', width: 1024, height: 1280 }],
      error: 'No images in ComfyUI output',
      seed: 0
    }
  }];
}

const image = images[0];
const COMFYUI = 'http://host.docker.internal:8188';
const imageUrl = COMFYUI
  + '/view?filename=' + encodeURIComponent(image.filename)
  + '&subfolder=' + encodeURIComponent(image.subfolder || '')
  + '&type=' + encodeURIComponent(image.type || 'output');

// Return in fal.ai-compatible format for downstream compatibility
return [{
  json: {
    complete: true,
    images: [{ url: imageUrl, width: 1024, height: 1280 }],
    imageUrl: imageUrl,
    prompt: $('Build ComfyUI Payload').first().json.originalPrompt || '',
    seed: $('Build ComfyUI Payload').first().json.seed || 0,
    conceptId: $('Build ComfyUI Payload').first().json.conceptId || 'X',
    recordId: $('Build ComfyUI Payload').first().json.recordId || ''
  }
}];

// Compliance Filter — blocks banned terms from reaching ComfyUI
// Prevents:
//   1) Product terms in scene descriptions (causes double product)
//   2) Text/typography terms (causes garbled text artifacts)
//   3) Medical claim language

const prompt = $json.prompt || '';
const errors = [];

// Guard 1: Product terms
const productBanned = /\b(massager|palmaura|device|product|gadget|hand\s*massag|electronic|appliance)\b/i;
if (productBanned.test(prompt)) {
  errors.push('Product term: ' + prompt.match(productBanned)[0]);
}

// Guard 2: Text/typography terms
const textBanned = /\b(text|font|overlay|says|reads|headline|logo|watermark|caption|typography|lettering|words|writing|label|slogan)\b/i;
if (textBanned.test(prompt)) {
  errors.push('Text term: ' + prompt.match(textBanned)[0]);
}

// Guard 3: Medical claim language
const medicalBanned = /\b(cure|heal|treat|diagnose|therapy|clinical|prescription|doctor.recommended|medical|therapeutic)\b/i;
if (medicalBanned.test(prompt)) {
  errors.push('Medical term: ' + prompt.match(medicalBanned)[0]);
}

if (errors.length > 0) {
  // Auto-clean instead of blocking
  let cleaned = prompt;
  cleaned = cleaned.replace(productBanned, '');
  cleaned = cleaned.replace(textBanned, '');
  cleaned = cleaned.replace(medicalBanned, '');
  cleaned = cleaned.replace(/\s{2,}/g, ' ').trim();

  return [{
    json: {
      ...$json,
      prompt: cleaned,
      complianceWarnings: errors,
      promptBeforeFilter: prompt
    }
  }];
}

return [{ json: { ...$json, complianceWarnings: [] } }];
